\documentclass{article}
\usepackage{amsmath}
\usepackage{hyperref}
\begin{document}
\section{Model}
The state evolves by
\begin{equation}
x_{t+1} = A x_t + B u_t
\label{eq:state}
\end{equation}
with process noise
\begin{equation}
w_t \sim \mathcal{N}(0, Q)
\label{eq:noise}
\end{equation}
The cost aggregates stage losses
\begin{equation}
J = \sum_{t=0}^{T} c(x_t, u_t)
\end{equation}
and the value satisfies
\begin{equation}
V(x) = \min_u \; c(x,u) + V(f(x,u))
\end{equation}
Energy decays as
\begin{equation}
E_{t+1} \leq \rho E_t
\end{equation}
while momentum follows
\begin{equation}
p_t = m v_t
\end{equation}
\section{Analysis}
The dynamics in \ref{eq:state} are linear, and \eqref{eq:noise} models the disturbance.
\autoref{eq:cost} defines the objective, while \ref{eq:cost} is reused below.
The Bellman form in \eqref{eq:bellman} is standard; energy decay in \ref{eq:energy} and momentum in \eqref{eq:momentum} close the argument.
\end{document}

